          phrases: [{ en: "What have you been seeing about this situation?", pt: "O que você tem visto sobre esta situação?" }, { en: "In my opinion, the public has been reacting strongly.", pt: "Na minha opinião, o público tem reagido fortemente." }, { en: "The police have been investigating this case for a week.", pt: "A polícia tem investigado este caso há uma semana." }],
