      lessonReview: { summary: { en: "In this unit, we learned about travel vocabulary and how to use the Past Continuous to talk about actions in progress that were interrupted by other actions. We also practiced expressions for meetings.", pt: "Nesta unidade, aprendemos sobre vocabulário de viagem e como usar o Past Continuous para falar sobre ações em andamento que foram interrompidas por outras ações. Também praticamos expressões para reuniões." }, canDo: [{ en: "I can talk about my past travel experiences, including unexpected interruptions.", pt: "Consigo falar sobre minhas experiências de viagem passadas, incluindo interrupções inesperadas." }, { en: "I can use Past Continuous with Simple Past to describe simultaneous or interrupting events.", pt: "Consigo usar o Past Continuous com o Simple Past para descrever eventos simultâneos ou que se interrompem." }, { en: "I can use common expressions to manage conversations in meetings.", pt: "Consigo usar expressões comuns para gerenciar conversas em reuniões." }], next: { en: "In the next unit, we will explore future plans and intentions using 'be going to'.", pt: "Na próxima unidade, exploraremos planos e intenções futuras usando 'be going to'." } },
