          examples: [{ en: "I had already left when they arrived.", pt: "Eu já tinha saído quando eles chegaram." }, { en: "She had finished the project before the deadline.", pt: "Ela tinha terminado o projeto antes do prazo." }, { en: "My computer had been working perfectly before that.", pt: "Meu computador estava funcionando perfeitamente antes disso." }],
          rule: { en: "We use the Past Perfect (had + past participle) to talk about an action that happened before another action in the past. It helps to show the order of events in a narrative.", pt: "Usamos o Past Perfect (had + past participle) para falar sobre uma ação que aconteceu antes de outra ação no passado. Ele ajuda a mostrar a ordem dos eventos em uma narrativa." },
