          phrases: [{ en: "I think artificial intelligence will revolutionize...", pt: "Acho que a inteligência artificial vai revolucionar..." }, { en: "Before this innovation, we had struggled with...", pt: "Antes desta inovação, nós tínhamos lutado com..." }, { en: "The new device will help where older software had failed.", pt: "O novo dispositivo ajudará onde softwares mais antigos tinham falhado." }],
